(()=>{if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init)}else{init()}
function init(){const mm=gsap.matchMedia();mm.add("(min-width: 1080px)",()=>{gsap.registerPlugin(ScrollTrigger);const dom=getDOM();if(!dom)return;const state={animations:null,isOnTop:!0,isSubmenuOpen:!1,activeItem:null,isSecondOpen:!1,scrollLocked:!1,activeSecond:null,secondSubmenuListener:null};const ctx=gsap.context(()=>{state.animations=createAnimations(dom,state);initEvents(dom,state)},dom.header);return()=>{resetMenu(dom,state);ctx.revert()}})}
function getDOM(){const header=document.getElementById('core-menu-desktop');if(!header)return null;const navContainer=header.querySelector('.main-menu-container');const menuItems=header.querySelectorAll('.menu-item');const theme=navContainer?.dataset.theme||'regular';const submenu=header.querySelector('#menu-submenu');const firstSubmenuWrapper=submenu?.querySelector('.first-wrapper');const firstSubmenu=submenu?.querySelector('.first-submenu');const secondSubmenuWrapper=submenu?.querySelector('.second-wrapper');const secondSubmenu=submenu?.querySelector('.second-submenu');if(!navContainer||!submenu||!firstSubmenuWrapper||!firstSubmenu||!secondSubmenuWrapper||!secondSubmenu||!theme){return null}
return{header,navContainer,menuItems,submenu,firstSubmenu,firstSubmenuWrapper,secondSubmenuWrapper,secondSubmenu,theme}}
function createAnimations(dom,state){state.scrollLocked=!1;const navTween=gsap.to(dom.navContainer,{padding:'12px 32px',paused:!0,duration:0.3,});const navScrollTrigger=ScrollTrigger.create({trigger:document.body,start:'100px top',end:'max',onUpdate:({direction})=>{if(state.scrollLocked)return;dom.navContainer.classList.toggle('is-at-top',direction==-1);dom.navContainer.classList.toggle('is-scrolled',direction==1);if(direction===1){navTween.play();state.isOnTop=!1}else{navTween.reverse();state.isOnTop=!0}}});const firstSubmenuTween=gsap.to(dom.firstSubmenuWrapper,{transform:'translateY(0%)',duration:0.5,ease:'circ.inOut',paused:!0,onStart:()=>{dom.firstSubmenuWrapper.style.visibility='visible';state.scrollLocked=!0;navTween.play()},onReverseComplete:()=>{dom.firstSubmenuWrapper.style.visibility='hidden';dom.header.classList.remove('is-open');state.scrollLocked=!1;if(state.isOnTop)navTween.reverse()},});const secondSubmenuTween=gsap.to(dom.secondSubmenuWrapper,{transform:'translateY(0%)',duration:0.4,ease:'circ.inOut',paused:!0,onReverseComplete:()=>{dom.secondSubmenuWrapper.style.display='none';dom.secondSubmenu.innerHTML=''}});const chevronTween=(chevron,open)=>{if(!chevron)return
return gsap.to(chevron,{rotate:open?180:0,duration:0.4,ease:'circ.out',})};const muteTween=(item,open)=>{if(!item)return
open?item.classList.add('mute'):item.classList.remove('mute');return gsap.to(item,{filter:open?"grayscale(100%) brightness(0.4)":"grayscale(0%) brightness(1)",duration:0.4,ease:'circ.out',})};const muteSiblings=(itemActive,open)=>{$(itemActive).closest('.menu-card').siblings('.menu-card').find('.card-wrapper .img-wrapper').each(function(){const img=$(this).find('img')[0];const svg=$(this).find('svg')[0];if(img){$(img).removeClass('active');muteTween(img,open)}
if(svg){muteTween(svg,open)}});$(itemActive).find('.img-wrapper img').toggleClass('active',open)};return{navTween,navScrollTrigger,firstSubmenuTween,secondSubmenuTween,chevronTween,muteSiblings}}
function initEvents(dom,state){document.body.classList.remove('no-scroll');dom.menuItems.forEach(item=>{item.addEventListener('click',(e)=>onMainItemClick(dom,state,item))});dom.submenu.addEventListener('click',(e)=>{const clickedInsideFirst=dom.firstSubmenuWrapper.contains(e.target);const clickedInsideSecond=dom.secondSubmenuWrapper.contains(e.target);if(!clickedInsideFirst&&!clickedInsideSecond){closeFirstSubmenu(dom,state)}});dom.firstSubmenuWrapper.addEventListener('click',(e)=>{const targetItem=e.target.closest('[data-submenu]');if(!targetItem)return;e.stopPropagation();onFirstSubmenuItemClick(dom,state,targetItem)})}
function onMainItemClick(dom,state,item){const key=item.dataset.menu;if(!key||!MENU_FIRST_SUBMENUS[key])return;if(state.isSubmenuOpen&&state.activeItem===item){if(state.isSecondOpen){closeSecondSubmenu(dom,state)}
closeFirstSubmenu(dom,state);return}
if(state.isSubmenuOpen&&state.activeItem!==item){closeSecondSubmenu(dom,state);closeFirstSubmenu(dom,state);state.openDelay=gsap.delayedCall(0.5,()=>{openFirstSubmenu(dom,state,item,key)});return}
openFirstSubmenu(dom,state,item,key)}
function openFirstSubmenu(dom,state,item,key){if(state.activeItem&&state.activeItem!==item){state.animations.chevronTween(state.activeItem.querySelector('svg'),!1)}
document.body.classList.add('no-scroll');dom.firstSubmenu.innerHTML=MENU_FIRST_SUBMENUS[key];dom.header.classList.add('is-open');state.animations.firstSubmenuTween.play();state.animations.chevronTween(item.querySelector('svg'),!0);state.isSubmenuOpen=!0;state.activeItem=item;state.isSecondOpen=!1;state.activeSecond=null}
function closeFirstSubmenu(dom,state){if(!state.isSubmenuOpen)return;if(state.isSecondOpen)closeSecondSubmenu(dom,state);document.body.classList.remove('no-scroll');state.animations.firstSubmenuTween.reverse();if(state.activeItem){state.animations.chevronTween(state.activeItem.querySelector('svg'),!1)}
state.isSubmenuOpen=!1;state.activeItem=null}
function onFirstSubmenuItemClick(dom,state,item){const key=item.dataset.submenu;if(!key||!MENU_SECOND_SUBMENUS[key])return;let activeKey=state.activeSecond?.dataset.submenu;if(state.isSecondOpen&&activeKey===key){state.animations.chevronTween(state.activeSecond.querySelector('.footer-card svg'),!1);state.animations.muteSiblings(state.activeSecond,!1);closeSecondSubmenu(dom,state);return}
if(state.isSecondOpen&&activeKey!==key){closeSecondSubmenu(dom,state);state.animations.secondSubmenuTween.eventCallback('onReverseComplete',()=>{state.animations.secondSubmenuTween.eventCallback('onReverseComplete',null);dom.secondSubmenuWrapper.style.display='none';dom.secondSubmenu.innerHTML='';openSecondSubmenu(dom,state,key,item)});return}
openSecondSubmenu(dom,state,key,item)}
function openSecondSubmenu(dom,state,key,item){dom.secondSubmenu.innerHTML=MENU_SECOND_SUBMENUS[key];dom.secondSubmenuWrapper.style.display='flex';state.animations.secondSubmenuTween.play();if(state.activeSecond&&state.activeSecond!==item){state.animations.chevronTween(state.activeSecond?.querySelector('.footer-card svg'),!1);state.animations.muteSiblings(state.activeSecond,!1)}
state.isSecondOpen=!0;state.activeSecond=item;state.animations.chevronTween(item.querySelector('.footer-card svg'),!0);state.animations.muteSiblings(item,!0);state.secondSubmenuListener=clickOnSecondSubmenuItem(dom,state)}
function closeSecondSubmenu(dom,state){if(!state.isSecondOpen)return;state.animations.chevronTween(state.activeSecond.querySelector('.footer-card svg'),!1);state.animations.muteSiblings(state.activeSecond,!1);state.animations.secondSubmenuTween.reverse();state.animations.secondSubmenuTween.eventCallback('onReverseComplete',null);state.isSecondOpen=!1;state.activeSecond=null;state.secondSubmenuListener?.destroy();state.secondSubmenuListener=null}
function clickOnSecondSubmenuItem(dom,state){if(!state.activeSecond)return;const handleClick=(e)=>{const link=e.target.closest('.second-submenu a');if(!link)return;e.stopPropagation();closeFirstSubmenu(dom,state)};const handleHoverEnter=(e)=>{const sbLink=e.target.closest('.sb-link[data-hover-img]');if(!sbLink)return;const preview=sbLink.closest('.inner-container')?.querySelector('.hover-preview');if(!preview)return;preview.querySelector('.preview-img').setAttribute('src',sbLink.dataset.hoverImg);preview.querySelector('.preview-img').setAttribute('alt',sbLink.dataset.hoverAlt||'');preview.classList.add('is-visible')};const handleHoverLeave=(e)=>{const sbLink=e.target.closest('.sb-link[data-hover-img]');if(!sbLink)return;sbLink.closest('.inner-container')?.querySelector('.hover-preview')?.classList.remove('is-visible')};dom.secondSubmenu.addEventListener('click',handleClick);dom.secondSubmenu.addEventListener('mouseenter',handleHoverEnter,!0);dom.secondSubmenu.addEventListener('mouseleave',handleHoverLeave,!0);return{destroy(){dom.secondSubmenu.removeEventListener('click',handleClick);dom.secondSubmenu.removeEventListener('mouseenter',handleHoverEnter,!0);dom.secondSubmenu.removeEventListener('mouseleave',handleHoverLeave,!0)}}}
function resetMenu(dom,state){state.openDelay?.kill();state.openDelay=null;state.animations?.firstSubmenuTween?.eventCallback('onReverseComplete',null);state.animations?.secondSubmenuTween?.eventCallback('onReverseComplete',null);state.animations?.secondSubmenuTween?.kill();state.animations?.firstSubmenuTween?.kill();state.animations?.navTween?.kill();state.animations?.navScrollTrigger?.kill();ScrollTrigger.getAll().forEach(st=>st.kill());gsap.set(dom.navContainer,{clearProps:"all"});dom.secondSubmenuWrapper.removeAttribute('style');dom.secondSubmenuWrapper.style.transform='translateY(-320%)';dom.secondSubmenuWrapper.style.display='none';dom.secondSubmenu.innerHTML='';dom.firstSubmenuWrapper.removeAttribute('style');dom.firstSubmenuWrapper.style.transform='translateY(-150%)';dom.firstSubmenuWrapper.style.visibility='hidden';dom.firstSubmenu.innerHTML='';dom.navContainer.classList.remove('is-scrolled','is-open');dom.navContainer.classList.add('is-at-top');dom.header.classList.remove('is-open');document.body.classList.remove('no-scroll');dom.menuItems.forEach(item=>{const chevron=item.querySelector('svg');if(chevron)gsap.set(chevron,{clearProps:"all"})});state.isSubmenuOpen=!1;state.isOnTop=!0;state.isSecondOpen=!1;state.activeItem=null;state.activeSecond=null;state.secondSubmenuListener?.destroy();state.secondSubmenuListener=null}})()